import{_ as i,o as n,c as e,a2 as l}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Kelola Alumni","description":"","frontmatter":{"title":"Kelola Alumni","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/admin/alumni.md","filePath":"latest/admin/alumni.md","lastUpdated":1786334463000}'),t={name:"latest/admin/alumni.md"};function r(s,a,u,m,o,d){return n(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="kelola-alumni" tabindex="-1">Kelola Alumni <a class="header-anchor" href="#kelola-alumni" aria-label="Permalink to &quot;Kelola Alumni&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul <strong>Kelola Alumni</strong> memungkinkan admin (dengan kemampuan <code>manage_alumni</code>) mengelola data alumni, termasuk <strong>memverifikasi profil</strong>, <strong>mengubah data</strong>, dan <strong>menghapus akun</strong> apabila diperlukan.</p><h2 id="membuka-halaman-kelola-alumni" tabindex="-1">Membuka Halaman Kelola Alumni <a class="header-anchor" href="#membuka-halaman-kelola-alumni" aria-label="Permalink to &quot;Membuka Halaman Kelola Alumni&quot;">​</a></h2><ol><li>Masuk dengan akun yang memiliki kemampuan <code>manage_alumni</code> (admin atau super admin).</li><li>Buka menu <strong>Admin</strong>, lalu pilih <strong>Kelola Alumni</strong>.</li><li>Daftar alumni ditampilkan beserta status verifikasi masing-masing.</li></ol><h2 id="memverifikasi-profil-alumni" tabindex="-1">Memverifikasi Profil Alumni <a class="header-anchor" href="#memverifikasi-profil-alumni" aria-label="Permalink to &quot;Memverifikasi Profil Alumni&quot;">​</a></h2><p>Verifikasi menandakan bahwa data profil alumni telah diperiksa dan dianggap valid. Alumni terverifikasi mendapatkan hak tambahan, yaitu <strong>membuat lowongan</strong> dan <strong>membuat pengumuman</strong>.</p><h3 id="memverifikasi-satu-alumni" tabindex="-1">Memverifikasi Satu Alumni <a class="header-anchor" href="#memverifikasi-satu-alumni" aria-label="Permalink to &quot;Memverifikasi Satu Alumni&quot;">​</a></h3><ol><li>Pada daftar alumni, cari alumni yang akan diverifikasi.</li><li>Periksa kelengkapan dan kebenaran datanya.</li><li>Klik tombol <strong>Verifikasi</strong>.</li><li>Status alumni berubah menjadi <strong>Terverifikasi</strong>.</li></ol><h3 id="verifikasi-massal-bulk" tabindex="-1">Verifikasi Massal (Bulk) <a class="header-anchor" href="#verifikasi-massal-bulk" aria-label="Permalink to &quot;Verifikasi Massal (Bulk)&quot;">​</a></h3><ol><li>Centang beberapa alumni pada daftar.</li><li>Klik tombol <strong>Verifikasi Massal</strong>.</li><li>Konfirmasi tindakan.</li><li>Seluruh alumni terpilih langsung terverifikasi.</li></ol><div class="warning custom-block"><p class="custom-block-title">Kehati-hatian</p><p>Verifikasi massal hanya boleh dilakukan jika <strong>seluruh data terpilih</strong> sudah dipastikan valid, misalnya setelah impor CSV dari sumber terpercaya.</p></div><h2 id="mengubah-data-alumni" tabindex="-1">Mengubah Data Alumni <a class="header-anchor" href="#mengubah-data-alumni" aria-label="Permalink to &quot;Mengubah Data Alumni&quot;">​</a></h2><ol><li>Pada daftar alumni, klik tombol <strong>Ubah</strong> pada alumni yang dituju.</li><li>Perbarui data yang diperlukan (nama, angkatan, pekerjaan, perusahaan, kontak, dan lain-lain).</li><li>Klik <strong>Simpan</strong>.</li></ol><h2 id="menghapus-akun-alumni" tabindex="-1">Menghapus Akun Alumni <a class="header-anchor" href="#menghapus-akun-alumni" aria-label="Permalink to &quot;Menghapus Akun Alumni&quot;">​</a></h2><p>Penghapusan akun bersifat permanen dan menghilangkan data pengguna beserta konten terkaitnya.</p><ol><li>Pada daftar alumni, klik tombol <strong>Hapus</strong>.</li><li>Konfirmasi penghapusan dengan teliti.</li><li>Akun dan data alumni dihapus dari sistem.</li></ol><div class="danger custom-block"><p class="custom-block-title">Hati-hati</p><p>Tindakan <strong>menghapus akun tidak dapat dibatalkan</strong>. Pastikan benar-benar diperlukan, misalnya atas permintaan pengguna sendiri atau pelanggaran berat.</p></div><h2 id="status-alumni" tabindex="-1">Status Alumni <a class="header-anchor" href="#status-alumni" aria-label="Permalink to &quot;Status Alumni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Belum Terverifikasi</strong></td><td>Profil terdaftar tetapi belum diperiksa admin.</td></tr><tr><td><strong>Terverifikasi</strong></td><td>Profil telah diperiksa dan dianggap valid; dapat membuat lowongan dan pengumuman.</td></tr></tbody></table><h2 id="tips-pengelolaan" tabindex="-1">Tips Pengelolaan <a class="header-anchor" href="#tips-pengelolaan" aria-label="Permalink to &quot;Tips Pengelolaan&quot;">​</a></h2><ul><li>Lakukan verifikasi setelah memeriksa data pada sumber resmi (misalnya data angkatan).</li><li>Gunakan impor CSV untuk pendataan awal, lalu verifikasi massal setelah data tervalidasi.</li><li>Tangani penghapusan akun dengan prosedur yang jelas dan terdokumentasi.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/admin/moderasi">Moderasi Konten</a> untuk meninjau laporan komunitas.</p>',23)])])}const p=i(t,[["render",r]]);export{h as __pageData,p as default};
